 public ExerciseModule(ClientModuleContext context,String host,int port){super(new BorderLayout(8,8));this.context=Objects.requireNonNull(context);this.connection=new AssignmentConnection(host,port,context.session().sessionId());setBorder(new EmptyBorder(10,10,10,10));sourceEditor.setFont(new Font(Font.MONOSPACED,Font.PLAIN,13));sourceEditor.setTabSize(4);contestSource.setFont(new Font(Font.MONOSPACED,Font.PLAIN,13));contestSource.setTabSize(4);catalogList.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);contestCatalogList.setSelectionMode(ListSelectionModel.MULTIPLE_INTERVAL_SELECTION);contestProblemList.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);contestSubmissionsList.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);workAssignments.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);classProgressList.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);progressStudentList.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);personalSubmissionsList.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
  JTabbedPane tabs=new JTabbedPane();if(context.session().isTeacher()){tabs.addTab("Ngân hàng bài",buildCatalog());tabs.addTab("Giao bài",buildTeacherAssignment());}tabs.addTab("Bài được giao",buildWork());if(context.session().isTeacher())tabs.addTab("Tiến độ lớp",buildHistory());
  add(tabs,BorderLayout.CENTER);add(status,BorderLayout.SOUTH);pollTimer=new javax.swing.Timer(2500,e->pollActiveSubmission());pollTimer.setRepeats(true);sharedCheckTimer=new javax.swing.Timer(2500,e->pollSharedCheck());sharedCheckTimer.setRepeats(true);contestPollTimer=new javax.swing.Timer(2500,e->pollContestSubmission());contestPollTimer.setRepeats(true);
  scope.addActionListener(e->{boolean individual="INDIVIDUAL".equals(scope.getSelectedItem());targetStudent.setEnabled(individual&&"BUILD_FROM_SCRATCH".equals(selectedCatalogMode));});targetStudent.setEnabled(false);
  targetStudent.addPopupMenuListener(new javax.swing.event.PopupMenuListener(){public void popupMenuWillBecomeVisible(javax.swing.event.PopupMenuEvent e){loadRoomStudents();}public void popupMenuWillBecomeInvisible(javax.swing.event.PopupMenuEvent e){}public void popupMenuCanceled(javax.swing.event.PopupMenuEvent e){}});
  workAssignments.addListSelectionListener(e->{if(!e.getValueIsAdjusting()&&!rebuildingAssignments)loadSelectedAssignment();});
  personalSubmissionsList.addListSelectionListener(e->{if(!e.getValueIsAdjusting()&&personalSubmissionsList.getSelectedValue()!=null)loadPersonalResult(personalSubmissionsList.getSelectedValue().id());});
  classProgressList.addListSelectionListener(e->{if(!e.getValueIsAdjusting()&&!rebuildingProgress)showClassProgressDetail();});
  progressStudentList.addListSelectionListener(e->{if(!e.getValueIsAdjusting()&&!rebuildingProgress)loadProgressSubmissionDetail();});
  contests.addActionListener(e->{if(contests.getSelectedItem()!=null)loadContestProblems();});contestProblemList.addListSelectionListener(e->{if(!e.getValueIsAdjusting()&&contestProblemList.getSelectedValue()!=null)selectContestProblem();});contestSubmissionsList.addListSelectionListener(e->{if(!e.getValueIsAdjusting()&&contestSubmissionsList.getSelectedValue()!=null)loadContestSubmissionResult(contestSubmissionsList.getSelectedValue().id());});
  context.addStateListener(()->SwingUtilities.invokeLater(()->{if(!context.roomState().inRoom()){loadedRoomId=null;status.setText("Hãy vào phòng StudyFix trước khi dùng Bài tập.");sharedCheckTimer.stop();contestPollTimer.stop();}else if(!Objects.equals(loadedRoomId,context.roomState().roomId())){loadedRoomId=context.roomState().roomId();loadAssignments();loadContests();if(context.session().isTeacher()){loadCatalog();loadRoomStudents();loadClassProgress();}}}));
  addHierarchyListener(e->{if((e.getChangeFlags()&java.awt.event.HierarchyEvent.DISPLAYABILITY_CHANGED)!=0&&!isDisplayable()){pollTimer.stop();sharedCheckTimer.stop();contestPollTimer.stop();}});
 }
