 private JPanel buildCatalog(){
  JPanel p=new JPanel(new BorderLayout(8,8)); JPanel top=new JPanel(new BorderLayout(6,6));
  JPanel filters=new JPanel(new GridLayout(1,4,6,0));filters.add(search);filters.add(topic);filters.add(modeFilter);JButton refresh=button("Tìm / tải ngân hàng");filters.add(refresh);top.add(filters,BorderLayout.NORTH);top.setBorder(new EmptyBorder(0,0,6,0));p.add(top,BorderLayout.NORTH);
  JSplitPane split=new JSplitPane(JSplitPane.HORIZONTAL_SPLIT,new JScrollPane(catalogList),new JScrollPane(catalogDetail));split.setResizeWeight(.35);p.add(split,BorderLayout.CENTER);
  refresh.addActionListener(e->loadCatalog());modeFilter.addActionListener(e->loadCatalog());topic.addActionListener(e->loadCatalog());search.addActionListener(e->loadCatalog());
  catalogList.addListSelectionListener(e->{if(!e.getValueIsAdjusting()&&catalogList.getSelectedValue()!=null){ExerciseRow row=catalogList.getSelectedValue();teacherExerciseId.setText(row.id());selectedCatalogMode=row.mode();teacherExerciseModeLabel.setText(displayMode(row.mode()));boolean debug="DEBUG_COLLAB".equals(row.mode());if(debug){scope.setSelectedItem("ROOM");scope.setEnabled(false);targetStudent.setEnabled(false);}else{scope.setEnabled(true);targetStudent.setEnabled("INDIVIDUAL".equals(scope.getSelectedItem()));}loadExerciseDetail(row.id());}});return p;
 }
 private JPanel buildTeacherAssignment(){
  JPanel p=new JPanel(new BorderLayout(10,10));JPanel form=new JPanel(new GridBagLayout());form.setBorder(new EmptyBorder(18,18,18,18));GridBagConstraints g=new GridBagConstraints();g.insets=new Insets(6,6,6,6);g.fill=GridBagConstraints.HORIZONTAL;g.weightx=1;
  addFormRow(form,g,0,"Bài đã chọn từ ngân hàng",teacherExerciseId);addFormRow(form,g,1,"Loại bài",teacherExerciseModeLabel);addFormRow(form,g,2,"Phạm vi giao",scope);addFormRow(form,g,3,"Học sinh trong phòng",targetStudent);addFormRow(form,g,4,"Hạn nộp tính từ hiện tại (phút, 0 = không hạn)",deadlineMinutes);
  JButton assign=button("Giao bài");JPanel actions=new JPanel(new FlowLayout(FlowLayout.LEADING));actions.add(assign);g.gridx=0;g.gridy=5;g.gridwidth=2;form.add(actions,g);
  JTextArea help=textArea();help.setText("Chọn bài trong Ngân hàng rồi giao. DEBUG_COLLAB chỉ giao cho cả phòng và code lỗi mẫu sẽ tự nạp nếu trạng thái phòng an toàn. BUILD_FROM_SCRATCH hỗ trợ giao cho cả phòng hoặc một học sinh trong danh sách thành viên. Server luôn kiểm tra quyền và đối tượng nhận bài.");
  p.add(form,BorderLayout.NORTH);p.add(new JScrollPane(help),BorderLayout.CENTER);assign.addActionListener(e->createAssignment());return p;
 }
